(x, y, t) => {
  const warp1 = (px, py) => [
    Math.sin(px*0.018+t*0.25)*18+Math.cos(py*0.013-t*0.18)*14+Math.sin((px+py)*0.009+t*0.15)*8,
    Math.cos(py*0.018-t*0.22)*18+Math.sin(px*0.016+t*0.3)*14+Math.cos((px-py)*0.011-t*0.12)*8
  ];
  const [w1x, w1y] = warp1(x, y);
  const [w2x, w2y] = warp1(x+w1x*0.5, y+w1y*0.5);
  const sx = x+w1x+w2x*0.4, sy = y+w1y+w2y*0.4;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.14,1.3,0.75],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*50,0.11,1.8,1.0]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2),ff=1/(1+d*0.003);
    aS+=Math.sin(d*f-t*sp)*w*ff;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*ff;
    hS+=Math.sin(d*f*1.3-t*sp*0.8+3)*w*ff*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,harm=hS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15+Math.sin(sx*0.08-t*1.8)*Math.cos(sy*0.06+t*1.2)*0.1;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3;
  const sp2=(Math.sin(dist*0.08+ang*2-t*2)+Math.sin(dist*0.06-ang*5+t*0.8))*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const tex=Math.sin(sx*0.3+t*0.5)*Math.sin(sy*0.25-t*0.4)*Math.sin((sx-sy)*0.15+t*0.3)*0.12;
  const rd=act-inh*0.7+bg*0.25+sp1+sp2+cell+harm*0.3;
  const reaction=Math.tanh(rd*2.0),blend=reaction*0.8+tex*0.2,v=blend*0.5+0.5;
  const pal=[[5,12,45],[10,45,85],[15,90,120],[25,150,145],[120,195,130],[210,200,90],[220,145,65],[190,75,55],[140,40,65],[70,20,55],[30,15,50],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15,edge=Math.abs(reaction)>0.75?1.12:1.0,glow=Math.max(0,reaction)*0.08;
  const vig=1-Math.sqrt((x-240)**2+(y-120)**2)*0.0012;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*255)*vig)|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*200)*vig)|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*150)*vig)|0
  ];
}
